        "startTimeUnixNano": "1788379202000000000",
        "endTimeUnixNano": "1788379203000000000"
      }]
    }]
  }]
}
OTEL_INVENTORY
for route in payments inventory; do
  status=$(curl -sS --max-time 10 --cacert /root/otel-client/ca.crt --cert /root/otel-client/client.crt --key /root/otel-client/client.key -H 'Content-Type: application/json' --data-binary "@$tmpdir/$route.json" -o "$tmpdir/$route.response" -w '%{http_code}' "https://$NODE_IP:4318/v1/traces")
